// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "GEMINI_API_BASE": "https://generativelanguage.googleapis.com",
  "GEMINI_MODEL_TEXT": "gemini-flash-latest",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "IMAGE_QUALITY_COVER": "high",
  "IMAGE_QUALITY_PAGE": "medium",
  "IMAGE_QUALITY_SMALL": "low",
  "GENERATE_SEPARATE_PREVIEWS": "false",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_REFRESH_TOKEN": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 120,
  "IDEA_BATCH_SIZE": 40,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Work out the backup destination:
//   AI Digital Product Factory / Etsy / <Category> / <Product Name>
// Folder names are sanitised because they end up inside a Drive query string.
const ctx = $input.first().json;
const product = ctx.product || {};
const publish = ctx.publish || {};
const metadata = product.metadata || {};

const clean = (value, fallback) => String(value || fallback)
  .replace(/[\\/:*?"<>|']/g, ' ')
  .replace(/[\x00-\x1f]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 120) || fallback;

return [{
  json: {
    run_id: ctx.run_id,
    factory: ctx.factory,
    prompt_version: ctx.prompt_version,
    product_name: metadata.product_name || product.product_name,
    category: metadata.category || 'Uncategorised',
    etsy_listing_id: publish.etsy_listing_id || null,
    folder_names: {
      root: 'AI Digital Product Factory',
      marketplace: 'Etsy',
      category: clean(metadata.category, 'Uncategorised'),
      product: clean(metadata.product_name || product.product_name, `product-${ctx.run_id}`),
    },
    parent_root: $('Factory Config').first().json.cfg.GDRIVE_ROOT_FOLDER_ID || 'root',
    folder_ids: {},
  },
}];

// Both branches land here: an existing folder from the search, or the
// folder that was just created. One shape out either way.
const plan = $('Build Backup Plan').first().json;
const found = $input.first().json;
const id = found?.files?.[0]?.id || found?.id;

if (!id) {
  throw new Error('Could not resolve the Google Drive folder for level: root');
}

return [{ json: { ...plan, folder_ids: { ...plan.folder_ids, root: id }, current_parent: id } }];

// Both branches land here: an existing folder from the search, or the
// folder that was just created. One shape out either way.
const plan = $('Resolve Root Folder').first().json;
const found = $input.first().json;
const id = found?.files?.[0]?.id || found?.id;

if (!id) {
  throw new Error('Could not resolve the Google Drive folder for level: marketplace');
}

return [{ json: { ...plan, folder_ids: { ...plan.folder_ids, marketplace: id }, current_parent: id } }];

// Both branches land here: an existing folder from the search, or the
// folder that was just created. One shape out either way.
const plan = $('Resolve Marketplace Folder').first().json;
const found = $input.first().json;
const id = found?.files?.[0]?.id || found?.id;

if (!id) {
  throw new Error('Could not resolve the Google Drive folder for level: category');
}

return [{ json: { ...plan, folder_ids: { ...plan.folder_ids, category: id }, current_parent: id } }];

// Both branches land here: an existing folder from the search, or the
// folder that was just created. One shape out either way.
const plan = $('Resolve Category Folder').first().json;
const found = $input.first().json;
const id = found?.files?.[0]?.id || found?.id;

if (!id) {
  throw new Error('Could not resolve the Google Drive folder for level: product');
}

return [{ json: { ...plan, folder_ids: { ...plan.folder_ids, product: id }, current_parent: id } }];

// One item per file to back up. The product export, the prepared marketplace
// packages and a workflow log all land in the same product folder.
const plan = $('Resolve Product Folder').first().json;
const ctx = $('Receive Backup Request').first().json;
const product = ctx.product || {};
const publish = ctx.publish || {};

const files = [...(product.files || []), ...(publish.extra_files || [])];

// Workflow log: what ran, what it cost, what came out.
const log = [
  `AI Digital Product Factory - workflow log`,
  `====================================================`,
  `Run id           : ${ctx.run_id}`,
  `Factory          : ${ctx.factory}`,
  `Product          : ${plan.product_name}`,
  `Category         : ${plan.category}`,
  `Prompt version   : ${ctx.prompt_version}`,
  `Started at       : ${ctx.started_at}`,
  `Backed up at     : ${new Date().toISOString()}`,
  ``,
  `Etsy listing id  : ${publish.etsy_listing_id || 'n/a'}`,
  `Etsy state       : ${publish.etsy_listing_state || 'n/a'}`,
  `Etsy images      : ${publish.uploaded_image_count || 0}`,
  `Gumroad package  : ${publish.gumroad_package_ready ? 'prepared' : 'skipped'}`,
  `MiriCanvas pkg   : ${publish.miricanvas_package_ready ? 'prepared' : 'skipped'}`,
  ``,
  `PDF pages        : ${product.stats?.pdf_pages ?? 'n/a'}`,
  `Content pages    : ${product.stats?.content_pages ?? 'n/a'}`,
  `Images generated : ${product.stats?.images?.generated ?? 'n/a'} / ${product.stats?.images?.requested ?? 'n/a'}`,
  `Placeholder art  : ${product.stats?.placeholder_images ? 'YES (dry run)' : 'no'}`,
  `Total bytes      : ${product.stats?.total_bytes ?? 'n/a'}`,
  `QA summary       : ${product.qa?.summary || 'n/a'}`,
  ``,
  `Files`,
  `-----`,
  ...files.map((f) => `- ${f.file_name} (${f.format}, ${f.bytes} bytes) - ${f.purpose}`),
].join('\n');

const all = [
  ...files,
  {
    key: 'workflow_log_txt',
    file_name: 'workflow-log.txt',
    format: 'TXT',
    mime_type: 'text/plain',
    purpose: 'run log',
    b64: Buffer.from(log, 'utf8').toString('base64'),
  },
];

return all.map((file, index) => ({
  json: {
    ...file,
    upload_index: index + 1,
    upload_total: all.length,
    parent_folder_id: plan.folder_ids.product,
  },
}));

// Manifest entry -> binary item for the Google Drive node.
const file = $input.first().json;
return [{
  json: {
    file_name: file.file_name,
    parent_folder_id: file.parent_folder_id,
    key: file.key,
    format: file.format,
  },
  binary: {
    data: {
      data: file.b64,
      mimeType: file.mime_type,
      fileName: file.file_name,
      fileExtension: (file.file_name.split('.').pop() || 'bin'),
    },
  },
}];

// Backup contract returned to 01.
const plan = $('Resolve Product Folder').first().json;
const uploads = $input.all().map((i) => i.json).filter((u) => u && (u.id || u.fileId));

return [{
  json: {
    ok: true,
    run_id: plan.run_id,
    drive_folder_id: plan.folder_ids.product,
    drive_folder_path: [
      plan.folder_names.root,
      plan.folder_names.marketplace,
      plan.folder_names.category,
      plan.folder_names.product,
    ].join('/'),
    drive_folder_ids: plan.folder_ids,
    uploaded_files: uploads.map((u) => ({
      id: u.id || u.fileId,
      name: u.name || u.file_name,
      web_link: u.webViewLink || null,
    })),
    uploaded_file_count: uploads.length,
    backed_up_at: new Date().toISOString(),
  },
}];
